mapper.select:
SELECT  FROM emp e 
e.deleted=1-#{onJob}e.deleted=0
AND (e.ename LIKE CONCAT('%',#{keyword},'%') OR e.job LIKE CONCAT('%',#{keyword},'%'))
AND e.job=#{post}AND e.deptno=#{deptId}
AND COALESCE(e.sal,0)+COALESCE(e.comm,0) >= #{minPay}
AND e.empno IN #{key}
ORDER BY COALESCE(e.sal,0)+COALESCE(e.comm,0) DESC,e.empnoORDER BY e.empno
